/* eslint-disable */
// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  spring,
  interpolate,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadPlayfair = makeLoadFont('PlayfairDisplay');
import { makePie } from "@remotion/shapes";
import { evolvePath } from "@remotion/paths";

// Load beautiful cursive italic serif font to match the sketch aesthetic
const { fontFamily: playfairFamily } = loadPlayfair();



export type ComponentNameProps = Record<string, any>;

const PieBarChartAnimation: React.FC<ComponentNameProps> = ({
  backgroundColor = "#f4edd9",
  transparentBackground = false,
  durationInSeconds = 6,
  pieRadius = 220,
  barMaxHeight = 280,
  blueValue = 28,
  yellowValue = 23,
  greenValue = 32,
  redValue = 17,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Background transparency logic
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Normalize percentages so they always sum up to 100% flawlessly
  const total = blueValue + yellowValue + greenValue + redValue;
  const bluePct = total > 0 ? blueValue / total : 0.28;
  const yellowPct = total > 0 ? yellowValue / total : 0.23;
  const greenPct = total > 0 ? greenValue / total : 0.32;
  const redPct = total > 0 ? redValue / total : 0.17;

  // Vibrant sketch-like colors
  const blueColor = "#0039b4";
  const yellowColor = "#e5b400";
  const greenColor = "#00b412";
  const redColor = "#b00808";

  // Coordinates & spacing (Responsive Layout)
  const cx = width * 0.5;
  const cy = height * 0.33; // Centered beautifully in top half
  const ox = width * 0.15;
  const oy = height * 0.82; // Baseline for bar chart
  const axisWidth = width * 0.7;
  const axisHeight = height * 0.32;

  // --- ANIMATIONS ---

  // 1. Overall Intro Zoom & Fade (paper reveal)
  const paperEntrance = spring({
    frame,
    fps,
    config: { damping: 15, stiffness: 60 },
  });
  const paperScale = interpolate(paperEntrance, [0, 1], [0.95, 1]);
  const paperOpacity = interpolate(paperEntrance, [0, 1], [0, 1]);

  // 2. Camera Movements (Phase 1, Phase 2, Phase 3)
  const cameraProgress = spring({
    frame: frame - 50,
    fps,
    config: { damping: 18, stiffness: 45 },
  });
  const cameraScale = interpolate(cameraProgress, [0, 1], [1.7, 1.0]);
  const cameraTranslateY = interpolate(cameraProgress, [0, 1], [height * 0.5 - cy, 0]);
  const barChartOpacity = interpolate(cameraProgress, [0.2, 0.8], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // 3. Pie Chart Scale-in Animation
  const pieScaleSpring = spring({
    frame: frame - 10,
    fps,
    config: { damping: 12, stiffness: 80 },
  });
  const currentPieRadius = pieRadius * interpolate(pieScaleSpring, [0, 1], [0, 1]);

  // 4. Sequential Progress Animations for each Slice
  const blueSpring = spring({
    frame: frame - 15,
    fps,
    config: { damping: 14, stiffness: 70 },
  });
  const yellowSpring = spring({
    frame: frame - 22,
    fps,
    config: { damping: 14, stiffness: 70 },
  });
  const greenSpring = spring({
    frame: frame - 29,
    fps,
    config: { damping: 14, stiffness: 70 },
  });
  const redSpring = spring({
    frame: frame - 36,
    fps,
    config: { damping: 14, stiffness: 70 },
  });

  // Calculate dynamic cascading progress and rotation
  const blueProgress = bluePct * blueSpring;
  const yellowProgress = yellowPct * yellowSpring;
  const greenProgress = greenPct * greenSpring;
  const redProgress = redPct * redSpring;

  const blueRotation = 0;
  const yellowRotation = blueProgress * Math.PI * 2;
  const greenRotation = (blueProgress + yellowProgress) * Math.PI * 2;
  const redRotation = (blueProgress + yellowProgress + greenProgress) * Math.PI * 2;

  // Path data generation (using R=100 for SVG internal viewbox scaling)
  const R_render = 100;
  const bluePie = makePie({ radius: R_render, progress: blueProgress, rotation: blueRotation });
  const yellowPie = makePie({ radius: R_render, progress: yellowProgress, rotation: yellowRotation });
  const greenPie = makePie({ radius: R_render, progress: greenProgress, rotation: greenRotation });
  const redPie = makePie({ radius: R_render, progress: redProgress, rotation: redRotation });

  // 5. Pointer Lines and Text Labels Calculations (Static reference with staggered draw-in)
  const getPointerPaths = (pctStart: number, pctSize: number) => {
    const angleMid = (pctStart + pctSize / 2) * Math.PI * 2;
    const rStart = pieRadius * 0.6;
    const rBend = pieRadius * 1.15;
    
    const x0 = cx + rStart * Math.sin(angleMid);
    const y0 = cy - rStart * Math.cos(angleMid);
    const x1 = cx + rBend * Math.sin(angleMid);
    const y1 = cy - rBend * Math.cos(angleMid);
    
    const isLeft = Math.sin(angleMid) < 0;
    const x2 = isLeft ? x1 - width * 0.08 : x1 + width * 0.08;
    const y2 = y1;

    const pathD = `M ${x0.toFixed(1)} ${y0.toFixed(1)} L ${x1.toFixed(1)} ${y1.toFixed(1)} L ${x2.toFixed(1)} ${y2.toFixed(1)}`;
    return { pathD, x2, y2, isLeft };
  };

  const bluePointers = getPointerPaths(0, bluePct);
  const yellowPointers = getPointerPaths(bluePct, yellowPct);
  const greenPointers = getPointerPaths(bluePct + yellowPct, greenPct);
  const redPointers = getPointerPaths(bluePct + yellowPct + greenPct, redPct);

  // Line drawing spring triggers (coordinated with Camera Phase 2 Zoom Out)
  const blueLineSpring = spring({ frame: frame - 55, fps, config: { damping: 15 } });
  const yellowLineSpring = spring({ frame: frame - 62, fps, config: { damping: 15 } });
  const greenLineSpring = spring({ frame: frame - 69, fps, config: { damping: 15 } });
  const redLineSpring = spring({ frame: frame - 76, fps, config: { damping: 15 } });

  const blueEvolution = evolvePath(blueLineSpring, bluePointers.pathD);
  const yellowEvolution = evolvePath(yellowLineSpring, yellowPointers.pathD);
  const greenEvolution = evolvePath(greenLineSpring, greenPointers.pathD);
  const redEvolution = evolvePath(redLineSpring, redPointers.pathD);

  // Label text animations (fade-in & count-up)
  const blueTextSpring = spring({ frame: frame - 65, fps, config: { damping: 12, stiffness: 90 } });
  const yellowTextSpring = spring({ frame: frame - 72, fps, config: { damping: 12, stiffness: 90 } });
  const greenTextSpring = spring({ frame: frame - 79, fps, config: { damping: 12, stiffness: 90 } });
  const redTextSpring = spring({ frame: frame - 86, fps, config: { damping: 12, stiffness: 90 } });

  const targetBlue = Math.round(bluePct * 100);
  const targetYellow = Math.round(yellowPct * 100);
  const targetGreen = Math.round(greenPct * 100);
  const targetRed = Math.round(redPct * 100);

  const blueCountVal = Math.round(interpolate(blueTextSpring, [0, 1], [0, targetBlue], { extrapolateRight: "clamp" }));
  const yellowCountVal = Math.round(interpolate(yellowTextSpring, [0, 1], [0, targetYellow], { extrapolateRight: "clamp" }));
  const greenCountVal = Math.round(interpolate(greenTextSpring, [0, 1], [0, targetGreen], { extrapolateRight: "clamp" }));
  const redCountVal = Math.round(interpolate(redTextSpring, [0, 1], [0, targetRed], { extrapolateRight: "clamp" }));

  // 6. Bar Chart Axis Animating-in (revealed during zoom out)
  const axisSpring = spring({ frame: frame - 50, fps, config: { damping: 15 } });
  const currentYTop = oy - axisHeight * axisSpring;
  const currentXRight = ox + axisWidth * axisSpring;

  // 7. Bars Growth Animations (Staggered and Bouncy)
  const barSpacing = axisWidth / 5;
  const barWidth = width * 0.09;

  // Maximum value representation for height normalization
  const maxVal = 0.35;
  const targetHRed = (redPct / maxVal) * barMaxHeight;
  const targetHGreen = (greenPct / maxVal) * barMaxHeight;
  const targetHYellow = (yellowPct / maxVal) * barMaxHeight;
  const targetHBlue = (bluePct / maxVal) * barMaxHeight;

  const barRedSpring = spring({ frame: frame - 60, fps, config: { damping: 12, stiffness: 85 } });
  const barGreenSpring = spring({ frame: frame - 67, fps, config: { damping: 12, stiffness: 85 } });
  const barYellowSpring = spring({ frame: frame - 74, fps, config: { damping: 12, stiffness: 85 } });
  const barBlueSpring = spring({ frame: frame - 81, fps, config: { damping: 12, stiffness: 85 } });

  const hRed = targetHRed * barRedSpring;
  const hGreen = targetHGreen * barGreenSpring;
  const hYellow = targetHYellow * barYellowSpring;
  const hBlue = targetHBlue * barBlueSpring;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        transform: `scale(${paperScale})`,
        opacity: paperOpacity,
        transition: "none",
        overflow: "hidden",
      }}
    >
      {/* 1. Vintage Graph Paper Grid */}
      <svg
        style={{
          position: "absolute",
          width: "100%",
          height: "100%",
          zIndex: 0,
          transition: "none",
        }}
      >
        <defs>
          <pattern id="grid" width="50" height="50" patternUnits="userSpaceOnUse">
            <path
              d="M 50 0 L 0 0 0 50"
              fill="none"
              stroke="rgba(110, 80, 50, 0.12)"
              strokeWidth="1.2"
            />
            <path
              d="M 25 0 L 25 50 M 0 25 L 50 25"
              fill="none"
              stroke="rgba(110, 80, 50, 0.06)"
              strokeWidth="0.6"
            />
          </pattern>
        </defs>
        <rect width="100%" height="100%" fill="url(#grid)" />
      </svg>

      {/* 2. Vignette shadow overlay for 3D paper feel */}
      <div
        style={{
          position: "absolute",
          inset: 0,
          background: "radial-gradient(circle, transparent 40%, rgba(0,0,0,0.1) 100%)",
          pointerEvents: "none",
          zIndex: 1,
          transition: "none",
        }}
      />

      {/* Camera Wrapper */}
      <div
        style={{
          position: "absolute",
          inset: 0,
          transform: `translateY(${cameraTranslateY}px) scale(${cameraScale})`,
          transformOrigin: `${cx}px ${cy}px`,
          transition: "none",
        }}
      >
        {/* 3. SVG Layer for Pie Chart & Pointers */}
        <div
          style={{
            position: "absolute",
            inset: 0,
            zIndex: 2,
            transition: "none",
          }}
        >
          {/* Dynamic Pie Chart */}
          <svg
            viewBox="0 0 200 200"
            style={{
              width: currentPieRadius * 2,
              height: currentPieRadius * 2,
              position: "absolute",
              left: cx - currentPieRadius,
              top: cy - currentPieRadius,
              overflow: "visible",
              transform: `rotate(-90deg)`, // Standardized math offset
              transformOrigin: "center",
              transition: "none",
            }}
          >
            {blueProgress > 0 && (
              <path
                d={bluePie.path}
                fill={blueColor}
                stroke="#202020"
                strokeWidth="1.2"
                style={{ transition: "none" }}
              />
            )}
            {yellowProgress > 0 && (
              <path
                d={yellowPie.path}
                fill={yellowColor}
                stroke="#202020"
                strokeWidth="1.2"
                style={{ transition: "none" }}
              />
            )}
            {greenProgress > 0 && (
              <path
                d={greenPie.path}
                fill={greenColor}
                stroke="#202020"
                strokeWidth="1.2"
                style={{ transition: "none" }}
              />
            )}
            {redProgress > 0 && (
              <path
                d={redPie.path}
                fill={redColor}
                stroke="#202020"
                strokeWidth="1.2"
                style={{ transition: "none" }}
              />
            )}
          </svg>

          {/* Pointer Lines and Text Labels */}
          <svg
            style={{
              position: "absolute",
              width: "100%",
              height: "100%",
              overflow: "visible",
              transition: "none",
            }}
          >
            {/* Blue Pointer */}
            <path
              d={bluePointers.pathD}
              fill="none"
              stroke="#222"
              strokeWidth="2.5"
              strokeLinecap="round"
              strokeDasharray={blueEvolution.strokeDasharray}
              strokeDashoffset={blueEvolution.strokeDashoffset}
              style={{ transition: "none" }}
            />
            {/* Yellow Pointer */}
            <path
              d={yellowPointers.pathD}
              fill="none"
              stroke="#222"
              strokeWidth="2.5"
              strokeLinecap="round"
              strokeDasharray={yellowEvolution.strokeDasharray}
              strokeDashoffset={yellowEvolution.strokeDashoffset}
              style={{ transition: "none" }}
            />
            {/* Green Pointer */}
            <path
              d={greenPointers.pathD}
              fill="none"
              stroke="#222"
              strokeWidth="2.5"
              strokeLinecap="round"
              strokeDasharray={greenEvolution.strokeDasharray}
              strokeDashoffset={greenEvolution.strokeDashoffset}
              style={{ transition: "none" }}
            />
            {/* Red Pointer */}
            <path
              d={redPointers.pathD}
              fill="none"
              stroke="#222"
              strokeWidth="2.5"
              strokeLinecap="round"
              strokeDasharray={redEvolution.strokeDasharray}
              strokeDashoffset={redEvolution.strokeDashoffset}
              style={{ transition: "none" }}
            />

            {/* Text: Blue (28%) */}
            <text
              x={bluePointers.isLeft ? bluePointers.x2 - 15 : bluePointers.x2 + 15}
              y={bluePointers.y2 + 12}
              textAnchor={bluePointers.isLeft ? "end" : "start"}
              fill="#222"
              style={{
                fontFamily: playfairFamily,
                fontSize: "44px",
                fontStyle: "italic",
                fontWeight: "600",
                opacity: blueTextSpring,
                transition: "none",
              }}
            >
              {blueCountVal}%
            </text>

            {/* Text: Yellow (23%) */}
            <text
              x={yellowPointers.isLeft ? yellowPointers.x2 - 15 : yellowPointers.x2 + 15}
              y={yellowPointers.y2 + 12}
              textAnchor={yellowPointers.isLeft ? "end" : "start"}
              fill="#222"
              style={{
                fontFamily: playfairFamily,
                fontSize: "44px",
                fontStyle: "italic",
                fontWeight: "600",
                opacity: yellowTextSpring,
                transition: "none",
              }}
            >
              {yellowCountVal}%
            </text>

            {/* Text: Green (32%) */}
            <text
              x={greenPointers.isLeft ? greenPointers.x2 - 15 : greenPointers.x2 + 15}
              y={greenPointers.y2 + 12}
              textAnchor={greenPointers.isLeft ? "end" : "start"}
              fill="#222"
              style={{
                fontFamily: playfairFamily,
                fontSize: "44px",
                fontStyle: "italic",
                fontWeight: "600",
                opacity: greenTextSpring,
                transition: "none",
              }}
            >
              {greenCountVal}%
            </text>

            {/* Text: Red (17%) */}
            <text
              x={redPointers.isLeft ? redPointers.x2 - 15 : redPointers.x2 + 15}
              y={redPointers.y2 + 12}
              textAnchor={redPointers.isLeft ? "end" : "start"}
              fill="#222"
              style={{
                fontFamily: playfairFamily,
                fontSize: "44px",
                fontStyle: "italic",
                fontWeight: "600",
                opacity: redTextSpring,
                transition: "none",
              }}
            >
              {redCountVal}%
            </text>
          </svg>
        </div>

        {/* 4. Bar Chart Axis SVG */}
        <svg
          style={{
            position: "absolute",
            width: "100%",
            height: "100%",
            zIndex: 2,
            overflow: "visible",
            opacity: barChartOpacity,
            transition: "none",
          }}
        >
          {/* Y Axis Line */}
          <path
            d={`M ${ox} ${currentYTop} L ${ox} ${oy}`}
            stroke="#222"
            strokeWidth="3.5"
            strokeLinecap="square"
            style={{ transition: "none" }}
          />
          {/* X Axis Line */}
          <path
            d={`M ${ox} ${oy} L ${currentXRight} ${oy}`}
            stroke="#222"
            strokeWidth="3.5"
            strokeLinecap="square"
            style={{ transition: "none" }}
          />
        </svg>

        {/* 5. Bar Elements */}
        <div
          style={{
            position: "absolute",
            inset: 0,
            zIndex: 3,
            pointerEvents: "none",
            opacity: barChartOpacity,
            transition: "none",
          }}
        >
          {/* Bar 1 (Red) */}
          <div
            style={{
              position: "absolute",
              left: ox + barSpacing * 1 - barWidth / 2,
              bottom: height - oy,
              width: barWidth,
              height: hRed,
              backgroundColor: redColor,
              border: "2.5px solid #222",
              borderBottom: "none",
              boxSizing: "border-box",
              transition: "none",
            }}
          />

          {/* Bar 2 (Green) */}
          <div
            style={{
              position: "absolute",
              left: ox + barSpacing * 2 - barWidth / 2,
              bottom: height - oy,
              width: barWidth,
              height: hGreen,
              backgroundColor: greenColor,
              border: "2.5px solid #222",
              borderBottom: "none",
              boxSizing: "border-box",
              transition: "none",
            }}
          />

          {/* Bar 3 (Yellow) */}
          <div
            style={{
              position: "absolute",
              left: ox + barSpacing * 3 - barWidth / 2,
              bottom: height - oy,
              width: barWidth,
              height: hYellow,
              backgroundColor: yellowColor,
              border: "2.5px solid #222",
              borderBottom: "none",
              boxSizing: "border-box",
              transition: "none",
            }}
          />

          {/* Bar 4 (Blue) */}
          <div
            style={{
              position: "absolute",
              left: ox + barSpacing * 4 - barWidth / 2,
              bottom: height - oy,
              width: barWidth,
              height: hBlue,
              backgroundColor: blueColor,
              border: "2.5px solid #222",
              borderBottom: "none",
              boxSizing: "border-box",
              transition: "none",
            }}
          />
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default PieBarChartAnimation;